import LogRocket from 'logrocket'

import NetworkError from './errors'
import internalize from './internalize'

// Environment variables are replaced in the bundle using the `DefinePlugin`
// in WebPack, so destructuring won't work here.
//
// See more:
// https://github.com/vercel/next.js/issues/6888#issuecomment-479862813
//
/* eslint-disable prefer-destructuring */
const API_URL = process.env.API_URL
const API_KEY = process.env.API_KEY
/* eslint-enable prefer-destructuring */

const prepareUrl = (pathname, base = API_URL) => {
  const url = /^\w+:\/\//.test(pathname) ? pathname : `${base}${pathname}`
  return new URL(url)
}

const prepareParams = ({ url, searchParams }) =>
  new URLSearchParams([
    ...Array.from(url.searchParams.entries()),
    ...Array.from(new URLSearchParams(searchParams).entries()),
  ])

const prepareMethod = ({ method = 'GET' }) => method.toUpperCase()

const prepareBody = ({ method, body }) => {
  if (!['GET', 'HEAD'].includes(method))
    return typeof body == 'object' ? JSON.stringify(body) : body
  return null
}

const prepareHeaders = ({ headers: customHeaders, body }) => {
  const defaultHeaders = {
    Accept: 'application/json',
    Authorization: `Bearer ${API_KEY}`,
  }
  const contentHeaders =
    typeof body == 'object' && body != null
      ? { 'Content-Type': 'application/json' }
      : {}

  return {
    ...defaultHeaders,
    ...contentHeaders,
    ...customHeaders,
  }
}

const prepareRequest = (init) => {
  const request = {}

  request.url = prepareUrl(init.url, API_URL)
  request.url.search = prepareParams({ ...init, url: request.url })
  request.url = request.url.toString()
  request.method = prepareMethod(init)
  request.headers = prepareHeaders(init)

  // Server-side: route through the in-cluster API service (skips CF/gateway).
  // No-op in the browser and when Internal_API isn't configured.
  const internal = internalize(request.url)
  request.url = internal.url
  request.headers = { ...request.headers, ...internal.headers }

  const body = prepareBody({ ...init, method: request.method })
  if (body != null) request.body = body

  request.credentials = 'include'

  return { ...init, ...request }
}

const processStatus = (response) => {
  if (response.status >= 400) {
    const StatusError = NetworkError.getErrorFromStatusCode(response.status)
    throw new StatusError(
      `Request for ${response.url} failed on ${response.status}`,
      response
    )
  }

  return response
}

const processBody = (response, { method }) => {
  const { status, headers } = response
  const type = headers.get('Content-Type')

  return (
    /application\/([\w.-]\+)?json/g.test(type) && method !== 'HEAD'
      ? response.json()
      : response.blob()
  ).then((data) => ({ data, type, status, headers }))
}

const processError = (error, details) => {
  const { response } = error
  if (response == null) throw error // re-throwing if nothing to process

  return processBody(response, details).then((body) => {
    Object.assign(error, body)

    // re-throwing after processing
    throw error
  })
}

const executeRequest = ({ url, ...options }) =>
  fetch(url, options)
    .then(processStatus)
    .then(
      (response) => processBody(response, { ...options }),
      (error) => {
        LogRocket.captureException(error)
        return processError(error, { ...options })
      }
    )
// For POST requests use variable - "body" and method:"POST"
const performRequest = (url, options) => {
  const request = prepareRequest({ url, ...options })
  return executeRequest(request)
}

export default performRequest

module.exports = (api) => {
  api.cache(true)

  const presets = [
    [
      '@babel/preset-env',
      {
        useBuiltIns: 'usage',
        corejs: 3,
      },
    ],
    '@babel/react',
  ]
  const plugins = [
    '@babel/plugin-proposal-export-default-from',
    [
      '@babel/plugin-proposal-decorators',
      {
        legacy: true,
      },
    ],
    '@babel/plugin-proposal-class-properties',
    '@babel/plugin-syntax-dynamic-import',
    'add-react-displayname',
    "@babel/plugin-transform-runtime",
  ]

  return {
    presets,
    plugins,
  }
}

import { useCallback, useEffect } from 'react'
import { useRouter } from 'next/router'
import ReactGA from 'react-ga4'
import { useCookie } from '@oacore/design'

const useAnalytics = () => {
  const analyticsAllowed = useCookie('analytics_cookies_allowed')

  const router = useRouter()
  const reportPageview = useCallback((url, title, type = 'search') => {
    ReactGA.send({
      hitType: type,
      page: url,
      title: `Search | ${window.location.search.substring(1)}`,
    })
  }, [])

  useEffect(() => {
    if (analyticsAllowed && process.env.NODE_ENV === 'production') {
      // Initialise production Google Analytics
      // console.log(process.env.GA_TRACKING_CODE)
      console.log("GA")

      ReactGA.initialize(process.env.GA_TRACKING_CODE)
    } else if (analyticsAllowed) {
      window.ga = (...args) =>
        // We want to have logging in the development environment
        // eslint-disable-next-line no-console
        console.log(`ga(${JSON.stringify(args).slice(1, -1)})`)
    }

    // Reporting first page view manually because the event doesn't fire
    reportPageview(router.asPath)

    // This clean-up is quite tricky
    return () => {
      window.ga = null
    }
  }, [])

  useEffect(() => {
    router.events.on('routeChangeComplete', reportPageview)

    return () => {
      router.events.off('routeChangeComplete', reportPageview)
    }
  }, [])
}

export default useAnalytics

import fs from 'fs'
import path from 'path'

import { internalize } from '../api/internalize'

// Hard cap on how long an SSR render will wait for the internal API.
// Without this, a slow/ratelimited api.core.ac.uk makes _app.getInitialProps
// hang forever, which wedges the whole Node event loop under load.
const FETCH_TIMEOUT_MS = 3000

class Loader {
  constructor(url, fileName) {
    this.baseUrl = url
    // path.resolve already yields an absolute path against process.cwd() (/app).
    this.fileName = path.resolve(fileName)
  }

  // eslint-disable-next-line class-methods-use-this
  log(...args) {
    if (process.env.NODE_ENV !== 'production')
      // eslint-disable-next-line no-console
      console.log(...args)
  }

  async fetchData(url) {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS)
    try {
      // Server-side: hit the in-cluster API service directly (skips CF/gateway).
      const internal = internalize(url)
      const res = await fetch(internal.url, {
        signal: controller.signal,
        headers: internal.headers,
      })
      if (res.status >= 400) throw new Error(`Bad status ${res.status}`)
      const data = await res.json()
      return { data, timestamp: new Date().getDate() }
    } finally {
      clearTimeout(timer)
    }
  }

  readCache() {
    try {
      // this.fileName is already absolute — do NOT join with __dirname.
      return JSON.parse(fs.readFileSync(this.fileName, 'utf8'))
    } catch (error) {
      this.log('data cache not initialized', error.message)
      return null
    }
  }

  writeCache(data) {
    try {
      fs.writeFileSync(this.fileName, JSON.stringify(data), 'utf8')
      this.log('Wrote to data cache')
    } catch (error) {
      this.log('Error writing data to file', error.message)
    }
  }

  async getData() {
    // 1. Serve from committed/warm cache if present — fast, never blocks.
    const cached = this.readCache()
    if (cached) return cached

    // 2. No cache — fetch live, bounded by timeout. On any failure
    //    (timeout, network, bad status) return null so SSR still renders.
    try {
      const data = await this.fetchData(this.baseUrl)
      this.writeCache(data)
      return data
    } catch (error) {
      this.log('live fetch failed, rendering without it', error.message)
      return null
    }
  }
}

export default Loader

import React, { useEffect, useState } from 'react'
import {
  Button,
  Card,
  DataProviderLogo,
  Link,
} from '@oacore/design/lib/elements'
import classNames from '@oacore/design/lib/utils/class-names'
import { Popover } from '@oacore/design/lib/modules'
import LogRocket from 'logrocket'

import redirect from '../../public/static/images/redirect.svg'
import styles from './styles.module.css'
import { capitalizeFirstLetter } from '../../utils/titleCase'

const DropDown = ({
  title,
  renderOAI,
  children,
  className,
  memberType,
  checkBillingType,
  activeArticle = false,
  useExpandButton = true,
  href,
  makeVisible,
  dataProviderId,
  disableRedirect,
  outputRedirect,
  metadata,
  coreDownloadUrl,
  sourceFulltextUrls,
  sourceFulltextUrlsUpd,
  id,
  oai,
  doi,
  useOtherVersions,
}) => {
  const [logoFetched, setLogoFetched] = useState('')

  const Tag = href ? Link : 'div'

  // eslint-disable-next-line consistent-return
  const redirectOnClick = () => {
    if (disableRedirect && activeArticle) return null

    window.location.href = href
  }

  const redirectToProviders = () => {
    window.location.href = `//core.ac.uk/data-providers/${dataProviderId}`
  }

  const getLogoLink = () => {
    useEffect(() => {
      async function fetchData() {
        try {
          const link = `https://api.core.ac.uk/data-providers/${dataProviderId}/logo`
          const response = await fetch(link)
          if (response.ok) setLogoFetched(link)
          else {
            LogRocket.captureMessage(
              `Failed to fetch logo. Status: ${response.status}`
            )
          }
        } catch (err) {
          console.error(err)
          LogRocket.captureException(err)
        }
      }

      if (dataProviderId) fetchData()
    }, [])

    return logoFetched
  }

  return (
    <>
      <div
        className={classNames
          .use({
            [styles.activeClass]: checkBillingType && !makeVisible,
            [styles.cardItem]: useOtherVersions,
          })
          .join(className)}
      >
        {checkBillingType && !makeVisible ? (
          <div className={styles.placement}>
            <a
              href="https://core.ac.uk/membership"
              className={styles.memberType}
            >
              {capitalizeFirstLetter(memberType?.billing_type)} member
            </a>
          </div>
        ) : (
          <></>
        )}
        <div className={styles.header}>
          <Tag className={styles.content}>
            <div
              className={classNames.use(styles.headerWrapper, {
                [styles.headerWrapperClickable]: useExpandButton,
              })}
            >
              {/* eslint-disable-next-line max-len */}
              {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events,jsx-a11y/no-static-element-interactions */}
              <div className={styles.itemWrapper} onClick={redirectToProviders}>
                <DataProviderLogo
                  imageSrc={checkBillingType ? getLogoLink() : ''}
                  useDefault
                  alt={title}
                  size="md"
                />
                <div className={styles.innerWrapper}>
                  <Card.Title
                    className={classNames.use(styles.title, {
                      [styles.titleColored]: !activeArticle,
                    })}
                    tag="h3"
                  >
                    {title}
                  </Card.Title>
                </div>
                <img
                  className={styles.redirectImg}
                  src={redirect}
                  alt="redirect"
                />
              </div>
            </div>
            <Card.Description
              className={classNames.use(styles.subtitle, {
                [styles.oaiTitle]: renderOAI,
              })}
              tag="span"
            >
              {outputRedirect && (
                <Button
                  onClick={redirectOnClick}
                  className={styles.actionButton}
                  variant="outlined"
                >
                  See this paper in CORE
                </Button>
              )}
              {oai ? (
                <a
                  className={styles.ellipsis}
                  href={`https://api.core.ac.uk/oai/${oai}`}
                >
                  <Button className={styles.actionButton} variant="outlined">
                    Go to the repository landing page
                  </Button>
                </a>
              ) : (
                <a className={styles.ellipsis} href={`https://doi.org/${doi}`}>
                  <Button className={styles.actionButton} variant="outlined">
                    Go to the repository landing page
                  </Button>
                </a>
              )}
              {coreDownloadUrl &&
              coreDownloadUrl.match(/core.ac.uk/gm) &&
              sourceFulltextUrls ? (
                <a
                  href={sourceFulltextUrlsUpd}
                  aria-labelledby={`${id}-downloaded-from-title`}
                  aria-describedby={`${id}-downloaded-from-body`}
                  target="_blank"
                  rel="noreferrer"
                >
                  <Button className={styles.actionButton} variant="outlined">
                    Download from data provider
                  </Button>
                </a>
              ) : (
                <Popover
                  placement="right"
                  content="We don't have a full text link from this data provider"
                  className={styles.popover}
                >
                  <Button className={styles.disabledButton} variant="outlined">
                    Download from data provider
                  </Button>
                </Popover>
              )}
              {renderOAI}
            </Card.Description>
          </Tag>
        </div>
        {children}
      </div>
    </>
  )
}

export default DropDown

import React from 'react'
import Head from 'next/head'
import { useRouter } from 'next/router'
import { Header } from '@oacore/design/lib/modules'

import ErrorCard from '../error-card'

import { findUrlsByType } from 'utils/helpers'
import log from 'utils/logger'
import { fetchWorks } from 'api/search'
import apiRequest from 'api'
import { useStore } from 'store'
import Template from 'templates/search'
import QueryError from 'templates/error/query'
import { transformDataProviders } from 'utils/data-providers-transform'
import { pickFeaturedMember } from 'templates/search/utils/featured-member'

export const getServerSideProps = async ({ query: searchParams }) => {
  if (Object.keys(searchParams).length === 0) {
    return {
      redirect: {
        permanent: true,
        destination: '/',
      },
      props: {},
    }
  }
  // TODO for nice response
  // const { q, page = 1, limit = 10, sort = 'recency' } = searchParams
  const { q, page = 1, limit = 10, sort = 'relevance', t } = searchParams

  const data = {
    currentPage: +page,
    query: q,
    sort,
  }

  if (page <= 1000) {
    const offset = page - 1 > 0 ? (page - 1) * 10 : page - 1

    const body = {
      q,
      offset,
      limit,
      t,
      exclude: ['fullText'],
      sort: sort === 'recent' ? 'recency' : sort,
    }
    const reqId = `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
    try {
      console.time(`fetchWorks:${reqId}`)
      const response = await fetchWorks(body)
      console.timeEnd(`fetchWorks:${reqId}`)

      if (response?.results) {
        console.time(`transformDataProviders:${reqId}`)
        const transformedWorks = await Promise.all(
          response.results.map(async (work) => {
            const articleWithUrls = findUrlsByType(work)
            return {
              ...articleWithUrls,
              dataProviders: await transformDataProviders(work.dataProviders),
            }
          })
        )
        console.timeEnd(`transformDataProviders:${reqId}`)

        Object.assign(data, {
          ...response,
          results: transformedWorks,
        })
      } else data.results = []
    } catch (error) {
      log(error)
      const queryError = {
        query: q,
        status: error?.status ?? null,
      }
      return {
        props: { queryError },
      }
    }
  } else data.results = []

  let members = []
  try {
    const { data: membersData } = await apiRequest('/members')
    members = (Array.isArray(membersData) ? membersData : []).filter(
      (member) => {
        const orgName = member?.organisation_name?.toLowerCase() || ''
        return (
          member?.billing_type !== 'starting' &&
          orgName &&
          !orgName.includes('test') &&
          !orgName.includes('demo')
        )
      }
    )
  } catch (membersError) {
    log(membersError)
  }

  const featuredMember = pickFeaturedMember(members)

  return {
    props: {
      data,
      members: featuredMember ? [featuredMember] : [],
    },
  }
}

const Search = ({ data, queryError, members }) => {
  const router = useRouter()

  const searchItem = router.query.q

  if (queryError?.status) return <ErrorCard />

  const { statistics } = useStore()
  const totalArticlesCount =
    statistics?.totalArticlesCount.toLocaleString('en-GB')
  Header.useSearchBar(
    {
      onQueryChanged: (searchTerm, pathName) => {
        router.push({
          pathname: pathName,
          query: {
            ...router.query,
            q: searchTerm,
            page: 1,
          },
        })
      },
      useAdvancedSearch: true,
      initQuery: data?.query,
      searchBarProps: {
        label: `Search ${totalArticlesCount} from papers around the world`,
        placeholder: `Search ${totalArticlesCount} from papers around the world`,
        prependIcon: '#magnify',
        changeOnBlur: false,
      },
    },
    { isHidden: false }
  )

  return (
    <div>
      {data?.results?.length >= 1 ? (
        <>
          <Head>
            <title>Search CORE</title>
          </Head>
          <Template data={data} members={members} />
        </>
      ) : (
        <QueryError query={searchItem} />
      )}
    </div>
  )
}

export default Search

/* eslint-disable jsx-a11y/anchor-is-valid */
import React, { useEffect, useRef, useState } from 'react'
import { Button, Icon, MathMarkdown } from '@oacore/design/lib/elements'
import { useRouter } from 'next/router'

import SimilarWorks from './similar-works'
import RelatedSearch from './related-search'
import FullTextThumbnail from './thumbnail-card'
import Metadata from './metadata'
import MapCard from './map-card'
import Keywords from './keywords'
import ReportCard from './report'
import CitationManager from './citation'
import styles from './styles.module.css'
import OtherVersions from './other-versions'

import { getAssetsPath } from 'utils/helpers'
import Search from 'modules/search-layout'

const ScientificOutputTemplate = ({
  data: {
    id,
    title,
    authors,
    abstract,
    publisher,
    publishedDate,
    dataProvider,
    updatedDate,
    sourceFulltextUrls,
    fulltextStatus,
    createdDate,
    tags,
    documentType,
    citations,
    outputs,
    reader: readerUrl,
    download,
    thumbnail_l: thumbnailLargeUrl,
    identifiers: { doi, oai },
    mainDataProviderLink,
    memberType,
    license,
  },
  useOtherVersions = false,
  ...passProps
}) => {
  const router = useRouter()

  const includeOai = router.asPath.includes('source=oai')
  const [uniqueDoiArray, setUiqueDoiArray] = useState([])
  const [oaiModal, setOaiModal] = useState(includeOai)

  const modalRef = useRef(null)

  const closeModal = () => {
    setOaiModal(false)
  }

  const handleClickOutside = (event) => {
    if (modalRef.current && !modalRef.current.contains(event.target))
      closeModal()
  }

  useEffect(() => {
    const doiArray = [doi]

    if (outputs) doiArray.push(...outputs.map((item) => item.doi.toLowerCase()))

    setUiqueDoiArray([...new Set(doiArray)])
  }, [])

  useEffect(() => {
    document.addEventListener('mousedown', handleClickOutside)

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [])

  const isTypeWorks = router.asPath.includes('/works/')
  const isTypeOutputs = router.asPath.includes('/outputs/')
  const pos = router.asPath.indexOf('search=')
  const resultSearch = `https://core.ac.uk/search/?${router.asPath.slice(
    pos + 7
  )}`

  return (
    <Search {...passProps} className={styles.outputContainer}>
      {oaiModal && !useOtherVersions && (
        <div ref={modalRef} className={styles.oaiModal}>
          <h3 className={styles.oaiModalTitle}>Repository landing page</h3>
          <div className={styles.oaiModalText}>
            We are not able to resolve this{' '}
            <a href="https://oai.core.ac.uk">OAI</a> Identifier to the
            repository landing page. If you are the repository manager for this
            record, please head to the{' '}
            <a href="https://core.ac.uk/services/repository-dashboard">
              Dashboard
            </a>{' '}
            and adjust the settings.
          </div>
          <div className={styles.oaiModalButtons}>
            <Button
              onClick={() => {
                window.open(
                  'https://core.ac.uk/services/repository-dashboard',
                  '_blank'
                )
              }}
              variant="contained"
            >
              Go to the Dashboard
            </Button>
            <Button onClick={closeModal} variant="text">
              Close
            </Button>
          </div>
        </div>
      )}
      <Search.Main>
        <div className={styles.background}>
          <div className={styles.navigationTrail}>
            <a href={resultSearch} target="_blank" rel="noreferrer">
              Search results
            </a>
            {(isTypeWorks || isTypeOutputs) && (
              <>
                <span className={styles.separator}>{'>'}</span>
                {isTypeWorks && <a href="#">Research work</a>}
                {isTypeOutputs && (
                  <a href="#">
                    Research output from {dataProvider?.name || 'repository'}
                  </a>
                )}
              </>
            )}
          </div>
          <div className={styles.info}>
            {documentType && (
              <span className={styles.documentType}>{documentType}</span>
            )}
            {oai && (
              <div className={styles.oai}>
                <img
                  src={getAssetsPath('/static/images/oai.svg')}
                  alt="oai"
                  className={styles.oaiLogo}
                />
                <a href={`https://api.core.ac.uk/oai/${oai}`}>{oai}</a>
              </div>
            )}
          </div>
          <h1>
            <MathMarkdown>{title}</MathMarkdown>
          </h1>
          <Metadata
            authors={authors}
            publishedDate={publishedDate}
            publisher={publisher}
            doi={doi}
            uniqueDoiArray={uniqueDoiArray}
          />
          <div className={styles.buttons}>
            {citations && citations.length > 0 && (
              <CitationManager
                data={{
                  citations,
                  actionLabel: 'Cite',
                }}
              />
            )}
            {useOtherVersions && mainDataProviderLink && (
              <Button
                variant="outlined"
                className={styles.actionButton}
                tag="a"
                target="_blank"
                href={mainDataProviderLink.link}
                key={mainDataProviderLink.id}
              >
                View <span>on</span> {mainDataProviderLink.name}
                <Icon src="#open-in-new" />
              </Button>
            )}
          </div>
        </div>
        <div className={styles.containerMain}>
          <section id="abstract" className={styles.abstract}>
            <h2>Abstract</h2>
            {abstract ? (
                <MathMarkdown>{abstract}</MathMarkdown>
            ) : (
              <span className={styles.abstractEmpty}>
                Abstract is not available.
              </span>
            )}
          </section>
          <Keywords tags={tags} />
          <SimilarWorks articleId={id} useOtherVersions={useOtherVersions} />
          <RelatedSearch articleId={id} articleTitle={title} />
        </div>
      </Search.Main>
      <Search.Sidebar className={styles.containerSidebar}>
        <FullTextThumbnail
          id={`full-text-thumbnail-${id}`}
          href={readerUrl}
          src={thumbnailLargeUrl || `//core.ac.uk/image/${id}/large`}
          alt="thumbnail-image"
          doi={doi}
          data={{
            title: !useOtherVersions ? dataProvider.name : null,
            dataProviderLogo: dataProvider.logo,
            updatedDate,
            sourceFulltextUrls,
            fulltextStatus,
            createdDate,
            oai,
            download,
          }}
          metadata={{
            hrefDataProvider: `//core.ac.uk/data-providers/${dataProvider.id}`,
          }}
          providerId={dataProvider.id}
          tag={fulltextStatus === 'disabled' ? 'div' : 'a'}
          useOtherVersions={useOtherVersions}
          memberType={memberType}
        />
        {useOtherVersions && outputs.length > 0 && (
          <OtherVersions
            useOtherVersions={useOtherVersions}
            outputs={outputs}
            metadata={{
              hrefDataProvider: `//core.ac.uk/data-providers/${dataProvider.id}`,
            }}
          />
        )}
        {!useOtherVersions && (
          <MapCard
            metadata={{
              name: dataProvider.name,
              location: dataProvider.location,
              hrefDataProvider: `//core.ac.uk/data-providers/${dataProvider.id}`,
            }}
          />
        )}

        {!useOtherVersions && (
          <ReportCard
            id={id}
            sourceFulltextUrls={sourceFulltextUrls}
            dataProvider={dataProvider.name}
          />
        )}
        {license && (
          <div className={styles.licenseWrapper}>
            Licence: <span className={styles.licenseType}>{license}</span>
          </div>
        )}
      </Search.Sidebar>
    </Search>
  )
}

export default ScientificOutputTemplate
